// ─── Sanitize & Build Gemini Request ─────────────────────────────────────────
const raw = $input.first().json;
let data = raw.body ?? raw;
if (typeof data === 'string') {
  try { data = JSON.parse(data); } catch(e) {}
}

const message   = String(data.message   || '').trim().slice(0, 2000);
const history   = Array.isArray(data.history) ? data.history : [];
const sessionId = String(data.sessionId || 'unknown');

if (!message || message.length < 2) {
  throw new Error('Empty or too-short message. Keys received: ' + JSON.stringify(Object.keys(data)));
}

// ─── System prompt built from property profile ────────────────────────────────
const PROPERTY_FACTS = `
Property: MAX Entertain Beachside Retreat — Amazing Backyard
Address: 1975 Point Nepean Road, Tootgarook VIC 3941 (Mornington Peninsula, ~1.5 hrs from Melbourne CBD)
Config: 6 bedrooms, 5 ensuites, 2 half-baths, sleeps 16+ guests
Sleeping: 4 King beds, 2 Bunk beds, 2 Singles, 2 Sofa beds, 3 cots available
Location: 10 metres from beach (across a road — not directly on sand)
Website: maxentertain.com | Direct booking saves guests 15%+

Signature features:
- Solar-heated pool + spa (usable most of the year)
- Home theatre with 120" projector
- Arcade & driving games, Nintendo Switch, karaoke
- Trampoline, mini golf, ping pong, pool table, foosball
- Under-tile heating, in-ceiling speakers
- Secure electric gate
- Pets welcome (must be disclosed at booking)

Check-in: 3:00 PM | Check-out: 10:00 AM

Cancellation policy:
- More than 14 days before check-in: full refund
- 7–14 days before check-in: 50% refund
- Less than 7 days before check-in: no refund

House rules:
- No parties or schoolies
- Noise alarms monitored
- Outdoor areas: 7am–11pm only
- Mornington Peninsula Shire Short Stay Accommodation Code of Conduct applies

Awards & social proof:
- Airbnb Host Awards 2024: Best Family Friendly Stay
- Booking.com Traveller Review Awards 2026
- 120+ five-star reviews, 1000+ guests per year

Nearby attractions:
- Moonah Links, National Golf Club, The Dunes (all within 10 min)
- Mornington Peninsula wineries, hot springs, beaches
- Sorrento, Portsea, Red Hill Market

Host: Jason (responsive, named in all guest reviews)
Contact / enquiry form: maxentertain.com/inquiry
OTA listings: Airbnb, Booking.com, VRBO
`;

const systemInstruction = [
  'You are MAX, the virtual concierge for MAX Entertain Beachside Retreat on the Mornington Peninsula, Victoria, Australia.',
  'You help guests with questions about the property, amenities, local area, policies, and bookings.',
  'ALWAYS reply in the same language the guest used. If the guest writes in Chinese, reply in Chinese. If in Japanese, reply in Japanese. Etc.',
  '',
  'Rules:',
  '- Answer using ONLY the facts in PROPERTY FACTS below. Never invent prices, availability, addresses, or policies.',
  '- If a question is not covered, say so honestly and direct the guest to the enquiry form at maxentertain.com/inquiry or to contact Jason directly.',
  '- Be warm, concise, and helpful. Use bullet points for lists.',
  '- Do NOT use markdown formatting. No **bold**, no *italic*, no headers. Plain text only.',
  '- If asked about something unrelated to the property or local area, politely redirect.',
  '- When guests ask about booking, always mention the direct-book discount: "Book directly at maxentertain.com and save 15%+ vs OTA prices."',
  '',
  'PROPERTY FACTS:',
  PROPERTY_FACTS
].join('\n');

// Build Gemini contents array (role: 'model' for assistant turns)
const contents = [
  ...history
    .filter(m => m.role === 'user' || m.role === 'assistant')
    .slice(-18)
    .map(m => ({
      role: m.role === 'assistant' ? 'model' : 'user',
      parts: [{ text: String(m.content).slice(0, 2000) }]
    })),
  { role: 'user', parts: [{ text: message }] }
];

const requestBody = JSON.stringify({
  system_instruction: { parts: [{ text: systemInstruction }] },
  contents,
  generationConfig: {
    maxOutputTokens: 700,
    temperature: 0.2
  }
});

return [{ json: { requestBody, sessionId } }];

// ─── Extract reply from Gemini response ──────────────────────────────────────
const data = $input.first().json;

if (data.error) {
  console.error('Gemini error:', data.error?.message || JSON.stringify(data.error));
  return [{ json: { reply: "MAX is unavailable right now. Please try again shortly or reach us via the enquiry form at maxentertain.com/inquiry." } }];
}

// Check for safety blocks
const candidate = data?.candidates?.[0];
if (candidate?.finishReason === 'SAFETY') {
  return [{ json: { reply: "I can't help with that. For property questions, feel free to ask anything about the retreat!" } }];
}

const raw_reply = candidate?.content?.parts?.[0]?.text || "I'm sorry, I couldn't generate a response. Please contact Jason via the enquiry form at maxentertain.com/inquiry.";
const reply = raw_reply.replace(/\*\*/g, '').replace(/\*/g, '').replace(/#{1,6} /g, '').trim();

return [{ json: { reply } }];
